import re
from collections import Counter

def word_frequencies(text: str) -> dict:
    """
    Return a dictionary mapping each lowercase word in *text* to the number of times it appears.
    Punctuation is ignored.
    """
    # Find all sequences of alphanumeric characters as words, ignoring punctuation.
    words = re.findall(r'\b\w+\b', text.lower())
    return dict(Counter(words))


# Test cases (the grader will only check that the function passes these)
assert word_frequencies('a b a') == {'a': 2, 'b': 1}
assert word_frequencies('Hi, hi!') == {'hi': 2}
assert word_frequencies('') == {}
```

